import json
BR={
"lhasa_apso":dict(name="Lhasa Apso",base={"line":"out/sets/line_p3/maltese__classic.jpg","geo":"out/sets/geo_p1/yorkshire_terrier__classic.jpg"},basename={"line":"maltese","geo":"yorkshire terrier"},
 tr="a LHASA APSO: a very long, heavy, perfectly STRAIGHT silky coat hanging straight down to the floor on both sides of the body and head, separated by a clean parting line running down the CENTER of the head and the middle of the back; the long hair falls forward over the eyes (eyes only just visible through it); a long beard and moustache; the pendant ears are completely hidden inside the hanging hair; a medium-length muzzle (clearly longer than a shih tzu or pug, not flat), black nose; sturdy body longer than tall; the feathered tail is curled up over the back. ABSOLUTELY NO topknot, NO ponytail, NO bow, NO hair-tie, NO upright tuft of hair on top of the head: the hair on the crown simply parts in the middle and falls down both sides"),
"miniature_pinscher":dict(name="Miniature Pinscher",base={"line":"out/sets/line_p2/doberman_pinscher__classic.jpg","geo":"out/sets/geo_p2/doberman_pinscher__classic.jpg"},basename={"line":"doberman","geo":"doberman"},
 tr="a MINIATURE PINSCHER (toy dog): sleek, very short smooth coat; compact, nearly square body with a short back; a small head with a rounded skull and a SHORT blunt wedge-shaped muzzle (much shorter than a doberman's); fairly large round dark eyes; medium-small erect triangular ears set high on the head, standing upright; short arched neck; straight slender fine legs with small cat-like paws; short tail carried up; proud alert high-stepping stance. It is NOT a doberman: no long narrow head, no long muzzle, no tall elegant neck, no big heavy chest, small proportional ears"),
"vira_lata":dict(name="Vira-lata (SRD Brazilian street dog)",base={"line":"out/sets/line_p3/american_pit_bull_terrier__classic.jpg","geo":"out/sets/geo_p3/american_pit_bull_terrier__classic.jpg"},basename={"line":"american pit bull terrier","geo":"american pit bull terrier"},
 tr="a VIRA-LATA, the typical Brazilian caramel mixed-breed street dog (SRD): medium size, lean and slim athletic body, short smooth coat, narrow chest, long slim legs; a modest narrow head with a lean wedge-shaped muzzle and a black nose; the ears are SEMI-ERECT triangular ears: they stand partly upright on top of the head and the tips fold forward, medium length (NOT long drooping beagle-style ears, NOT fully erect, NOT large); a simple clean face with no patches and no markings; alert friendly eyes; a long thin tail with a gentle upward curve. It must NOT look like a beagle, labrador, pit bull or hound: no long floppy ears, no tricolor beagle pattern, no heavy square jaw"),
}
DESC={"line":"single flowing continuous hand-drawn line","geo":"bold geometric polygon lines"}
KEEP=(" KEEP from image 1 exactly: the drawing technique, line weight, level of detail, composition (small FRONT head emblem on the left, full-body SITTING dog on the right, facing the viewer), size and positions. Eyes: draw each eye as one simple round ring outline with a solid black round pupil, both eyes identical and looking at the viewer. "
"Both drawings must be complete and clearly the same breed: all ears fully drawn, the tail fully drawn and clearly visible, chest and body contour lines on the sitting dog, legs and paws complete. Pure black lines on flat pure white, no gray, no shading, no fills except the nose, no text, nothing cut off or touching the canvas edge or each other.")
jobs=[]
for slug,b in BR.items():
  for th in("line","geo"):
    pr=(f"Image 1 is an APPROVED finished design of a {b['basename'][th]} in {DESC[th]} style. Redraw the whole design as {b['tr']}. Change the dog's identity completely (head shape, ears, coat, proportions, tail) so it is instantly recognizable as the new breed and does not resemble the {b['basename'][th]} of image 1 in anatomy; keep only the artistic style."+KEEP+" Plain classic version with no accessories, no collar, no sunglasses, no hearts.")
    jobs.append({"id":f"M_{th}_{slug}_classic","refs":[b["base"][th]],"aspect":"3:2","prompt":pr})
json.dump(jobs,open("scripts/nb_jobs1.json","w"),indent=1); print(len(jobs))
